CATALOG_FLAG_ANCHOR = '    }\n  ],\n  "operations": ['
CATALOG_OP_ANCHOR = '    {\n      "name": "dependencies",'
CATALOG_EXTENDS = [
    ('"valueName": "path",\n      "operations": ["graph", "show", "incremental", "concurrency"],', '"valueName": "path",\n      "operations": ["graph", "show", "incremental", "concurrency", "units"],'),
    ('"value": "none",\n      "operations": ["graph", "show", "incremental", "concurrency", "capacity", "leases", "cache"],', '"value": "none",\n      "operations": ["graph", "show", "incremental", "concurrency", "capacity", "leases", "cache", "units"],'),
    ('"name": "--root",\n      "value": "required",\n      "valueName": "path",\n      "operations": ["incremental", "concurrency"],', '"name": "--root",\n      "value": "required",\n      "valueName": "path",\n      "operations": ["incremental", "concurrency", "units"],'),
]
SCHEMA_OLD = '"incremental", "concurrency", "dependencies"'
SCHEMA_NEW = '"incremental", "concurrency", "units", "dependencies"'
ROUTER_ANCHOR = ' if(selected.args[0]==="concurrency"){const{runConcurrencyV1}=await import("./📏️incremental/🤝️concurrent/⌨️command/🟦️.ts");await runConcurrencyV1(root,selected.args,parent);return;}\n'
ROUTER_NEW = ROUTER_ANCHOR + ' if(selected.args[0]==="units"){const{runUnitsCliV1}=await import("./🧩️units/⌨️command/🟦️.ts");await runUnitsCliV1(root,selected.args,parent);return;}\n'


def indent(text, spaces):
    pad = " " * spaces
    return "\n".join(pad + line if line else line for line in text.split("\n"))


def catalog_edit(text):
    if '"name": "units"' in text:
        return text
    if text.count(CATALOG_FLAG_ANCHOR) != 1 or text.count(CATALOG_OP_ANCHOR) != 1:
        raise SystemExit("DRIFT: catalogue anchors are not unique")
    for old, new in CATALOG_EXTENDS:
        if text.count(old) != 1:
            raise SystemExit("DRIFT: catalogue flag anchor is not unique: " + old[:60])
        text = text.replace(old, new)
    flags = ",\n".join(indent(json.dumps(flag, ensure_ascii=False, indent=2), 4) for flag in UNITS_FLAGS)
    text = text.replace(CATALOG_FLAG_ANCHOR, "    },\n" + flags + "\n  ],\n  \"operations\": [")
    operation = indent(json.dumps(UNITS_OPERATION, ensure_ascii=False, indent=2), 4)
    text = text.replace(CATALOG_OP_ANCHOR, operation + ",\n" + CATALOG_OP_ANCHOR)
    json.loads(text)
    return text


def schema_edit(text):
    if '"units"' in text:
        return text
    if text.count(SCHEMA_OLD) != 1:
        raise SystemExit("DRIFT: schema OperationName anchor is not unique")
    return text.replace(SCHEMA_OLD, SCHEMA_NEW)


def router_edit(text):
    if "runUnitsCliV1" in text:
        return text
    if text.count(ROUTER_ANCHOR) != 1:
        raise SystemExit("DRIFT: router anchor is not unique")
    return text.replace(ROUTER_ANCHOR, ROUTER_NEW)
